const $=id=>document.getElementById(id);let token='';const notice=s=>$('notice').textContent=s;
async function api(path,method='GET',data){const r=await fetch('/api/admin/'+path,{method,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
async function safe(fn){try{await fn()}catch(e){notice(e.message)}}
function row(parent,values){const r=document.createElement('tr');for(const v of values){const c=document.createElement('td');c.textContent=v;r.append(c)}parent.append(r);return r}
function key(value=''){$('key').value=value;$('key-wrap').hidden=!value;$('clear-key').hidden=!value}
async function load(){const t=token,[a,b]=await Promise.all([api('accounts'),api('audit')]);if(!token||t!==token)return;for(const id of ['rows','events'])$(id).replaceChildren();for(const x of a.items){const r=row($('rows'),[x.username,x.role,x.enabled?'Actif':'Désactivé',x.activated?'Activé':'À activer',x.mfa_enabled?'Activé':'Non activé',({NONE:'Non envoyée',PENDING:'En attente',ACCEPTED:'Acceptée par Resend',FAILED:'Échec',CANCELLED:'Annulée'})[x.invitation_state]||'—','']);for(const [action,label] of [['DISABLE','Désactiver'],['ROTATE','Renouveler / réactiver'],['INVITE','Invitation REC']]){const btn=document.createElement('button');btn.textContent=label;btn.disabled=Boolean(x.self)||(action==='INVITE'&&(!x.enabled||x.activated||x.invitation_state!=='NONE'));if(x.self)btn.title='Votre propre compte';btn.onclick=()=>safe(async()=>{if(!confirm(label+' '+x.username+' ?'))return;if(action!=='INVITE')key();const d=await api('accounts/'+x.id,'PATCH',{action});if(action!=='INVITE')key(d.key);await load();if(action==='INVITE')notice('Invitation de test planifiée. Aucune clé envoyée par e-mail.')});r.lastChild.append(btn)}}for(const e of b.items)row($('events'),[e.created_at,e.actor,e.action,e.resource])}
$('login-form').onsubmit=async e=>{e.preventDefault();token=$('token').value;$('token').value='';try{await load();$('login').hidden=true;$('workspace').hidden=false}catch(e){token='';notice(e.message)}};
$('logout').onclick=()=>{token='';key();$('rows').replaceChildren();$('events').replaceChildren();$('create').reset();$('workspace').hidden=true;$('login').hidden=false;notice('Déconnecté.')};$('clear-key').onclick=()=>key();
$('create').onsubmit=e=>{e.preventDefault();safe(async()=>{const b=e.submitter;b.disabled=true;try{key();const d=await api('accounts','POST',Object.fromEntries(new FormData(e.target)));key(d.key);e.target.reset();await load();notice('Compte créé.')}finally{b.disabled=false}})};
